ификат по иностранному языку (достаточный балл) или собеседование","en":"Foreign-language certificate (sufficient score) or interview"}]},{"id":"kiut-preschool-education","name":{"uz":"Preschool Education","ru":"Preschool Education","en":"Preschool Education"},"subjects":[]},{"id":"kiut-primary-education","name":{"uz":"Primary Education","ru":"Primary Education","en":"Primary Education"},"subjects":[]},{"id":"kiut-history","name":{"uz":"History","ru":"History","en":"History"},"subjects":[]},{"id":"kiut-special-pedagogy","name":{"uz":"Special Pedagogy","ru":"Special Pedagogy","en":"Special Pedagogy"},"subjects":[]},{"id":"kiut-psychology","name":{"uz":"Psychology","ru":"Psychology","en":"Psychology"},"subjects":[]},{"id":"kiut-physical-culture","name":{"uz":"Physical Culture","ru":"Physical Culture","en":"Physical Culture"},"subjects":[]}]},{"id":"kiut-arts","name":{"uz":"School of Arts","ru":"School of Arts","en":"School of Arts"},"directions":[{"id":"kiut-fashion-design","name":{"uz":"Fashion Design","ru":"Fashion Design","en":"Fashion Design"},"subjects":[{"uz":"Ijodiy imtihon: rasm va kompozitsiya","ru":"Творческий экзамен: рисунок и композиция","en":"Creative exam: drawing and composition"}]},{"id":"kiut-painting","name":{"uz":"Painting","ru":"Painting","en":"Painting"},"subjects":[{"uz":"Ijodiy imtihon","ru":"Творческий экзамен","en":"Creative exam"}]},{"id":"kiut-interior-design","name":{"uz":"Interior Design","ru":"Interior Design","en":"Interior Design"},"subjects":[{"uz":"Ijodiy imtihon","ru":"Творческий экзамен","en":"Creative exam"}]}]}]},{"id":"uni-millat-umidi","name":"Millat Umidi University","shortName":"MU","city":"Tashkent","country":"Uzbekistan","website":"https://millatumidi.uz","published":true},{"id":"uni-cau","name":"Central Asian University (formerly AKFA University)","shortName":"CAU","city":"Tashkent","website":"https://centralasian.uz","published":true},{"id":"uni-tuit","name":"Tashkent University of Information Technologies named after Muhammad al-Khwarizmi","shortName":"TUIT","city":"Tashkent","country":"Uzbekistan","website":"https://tuit.uz","logoUrl":"/universities/uni-tuit.png","published":true}]$uni$::jsonb;
  stored jsonb;
  missing jsonb;
BEGIN
  SELECT "tenantId" INTO t FROM "Course" WHERE "id" = 'c-general-english' AND "deletedAt" IS NULL;
  IF t IS NULL THEN
    RAISE NOTICE 'university sync: no ILMORA catalog in this database, nothing to do';
    RETURN;
  END IF;
  SELECT COALESCE("data"->'universities', '[]'::jsonb) INTO stored FROM "SiteConfig" WHERE "tenantId" = t;
  IF stored IS NULL OR jsonb_typeof(stored) <> 'array' THEN
    RAISE NOTICE 'university sync: no site settings with a university list, nothing to do';
    RETURN;
  END IF;
  SELECT COALESCE(jsonb_agg(s.u ORDER BY s.i), '[]'::jsonb) INTO missing
    FROM jsonb_array_elements(seed) WITH ORDINALITY AS s(u, i)
    WHERE NOT EXISTS (SELECT 1 FROM jsonb_array_elements(stored) AS x(v) WHERE x.v->>'id' = s.u->>'id');
  IF jsonb_array_length(missing) = 0 THEN
    RAISE NOTICE 'university sync: all % universities already present, nothing to do', jsonb_array_length(seed);
    RETURN;
  END IF;

  BEGIN
    INSERT INTO "AuditEvent" ("id", "tenantId", "action", "entityType", "entityId", "before", "after", "reason")
    SELECT 'university-sync-20261105-SiteConfig', t, 'content.sync', 'SiteConfig', t,
      jsonb_build_object('version', "version", 'universities', "data"->'universities'),
      jsonb_build_object('addedUniversities', (SELECT jsonb_agg(m.v->>'id') FROM jsonb_array_elements(missing) AS m(v))),
      'University Preparation: universities added for the public page (packages not added)'
    FROM "SiteConfig" WHERE "tenantId" = t
    ON CONFLICT ("id") DO NOTHING;
    UPDATE "SiteConfig" SET "data" = jsonb_set("data", '{universities}', stored || missing), "version" = "version" + 1, "updatedAt" = CURRENT_TIMESTAMP
      WHERE "tenantId" = t;
    RAISE NOTICE 'university sync: % added, % already present', jsonb_array_length(missing), jsonb_array_length(seed) - jsonb_array_length(missing);
  EXCEPTION WHEN OTHERS THEN
    RAISE NOTICE 'university sync failed and was rolled back: %', SQLERRM;
  END;
END
$sync$;
